type parser struct { toks []Token; pos int }
func (p *parser) got(k Kind) bool { if p.toks[p.pos].Kind != k { return false }; p.pos++; return true }
func (p *parser) expr() (Node, error) {
    left, err := p.term(); if err != nil { return nil, err }
    for p.toks[p.pos].Kind == Plus || p.toks[p.pos].Kind == Minus {  // loop, not left recursion
        op := p.toks[p.pos]; p.pos++
        right, err := p.term(); if err != nil { return nil, err }
        left = Binary{op, left, right}
    }
    return left, nil
}
